--
-- Table structure for table `opportunity`
--

DROP TABLE IF EXISTS `opportunity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `opportunity` (
  `opportunity_id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `contact_id` int(11) NOT NULL,
  `lead_id` int(11) NOT NULL,
  `opportunity_status` enum('Prospecting','Qualification','Negotiating','Approval','Closed Loss','Closed Won') NOT NULL DEFAULT 'Prospecting',
  `opportunity_title` varchar(255) DEFAULT NULL,
  `opportunity_cost` decimal(15,2) DEFAULT NULL,
  `opportunity_details` text DEFAULT NULL,
  `date` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`opportunity_id`),
  KEY `company_id` (`company_id`),
  KEY `contact_id` (`contact_id`),
